// 按名字取图标；要填充版但这个图标没有时，用线性版。
func svgIcon(c *ui.Context, name string, filled bool) ui.Element {
	icon := iconRegular[name]
	if fill, ok := iconFill[name]; filled && ok {
		icon = fill
	}
	return ui.Icon(c, icon).Size(iconSize, iconSize)
}
